    }

    /// Join a user-scoped transient (ephemeral) thread
    public static func joinUserTransient(socket: Socket, key: String, afterCursor: String? = nil, beforeCursor: String? = nil, includeMetadata: Bool? = nil, limit: Int? = nil) async throws -> ApiChatChannel {
        let topic = topicUserTransient(key: key)
        let channel = socket.channel(topic)
        var payload: [String: JSONValue] = [:]
        if let afterCursor = afterCursor {
            payload["after_cursor"] = .string(afterCursor)
        }
        if let beforeCursor = beforeCursor {
            payload["before_cursor"] = .string(beforeCursor)
        }
        if let includeMetadata = includeMetadata {
            payload["include_metadata"] = .bool(includeMetadata)
        }
        if let limit = limit {
            payload["limit"] = .int(limit)
        }
        let joinResponse = try await channel.join(.object(payload))
        return ApiChatChannel(channel: channel, joinResponse: joinResponse)
    }

    /// Leave the underlying channel.
    public func leave() async throws {
        try await channel.leave()
    }

